template_css:
:root {
  --token-font-display: "Playfair Display", "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Times New Roman", serif;
  --token-font-body: "Inter", "Helvetica Neue", Helvetica, Arial, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;

  --token-space-2xs: 8px;
  --token-space-xs: 12px;
  --token-space-sm: 16px;
  --token-space-md: 24px;
  --token-space-lg: 32px;
  --token-space-xl: 40px;
  --token-space-2xl: 46px;

  --token-type-kicker: 22px;
  --token-type-heading: 64px;
  --token-type-body: 28px;
  --token-type-metric-value: 66px;
  --token-type-metric-label: 20px;

  --token-radius-card: var(--radius-card);
  --token-radius-pill: var(--radius-pill);
  --token-shadow-title: var(--frame-title-shadow);
  --token-shadow-caption: var(--frame-caption-shadow);

  --heading-max-lines: 5;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
}

.absolute {
  position: absolute;
}

.inset-0 {
  inset: 0;
}

/* ─────────────────────────────────────────
   Frame (root canvas)
   ───────────────────────────────────────── */

.frame {
  position: relative;
  isolation: isolate;
  overflow: hidden;

  --frame-bg: var(--color-surface-base);
  --frame-overlay-top: linear-gradient(180deg, transparent, color-mix(in srgb, var(--color-overlay-strong) 32%, transparent));
  --frame-overlay-bottom: linear-gradient(0deg, transparent, transparent);
  --frame-vignette: none;
  --frame-brand-pill-bg: transparent;
  --frame-brand-pill-border: var(--color-border-subtle);
  --frame-brand-pill-text: var(--color-text-primary);
  --frame-title-shadow: none;
  --frame-caption-shadow: none;
  --frame-grain-opacity: 0;
  --frame-image-opacity: 0.5;
  --frame-type-scale: 1;
  --frame-space-scale: 1;
}

.frame.frame-tone-dark,
.frame[data-template-tone="dark"] {
  --color-text-primary: #f2f2f2;
  --color-text-secondary: #d1d1d1;
  --color-text-muted: #9a9a9a;
  --color-surface-base: #070707;
  --color-surface-elevated: #131313;
  --color-border-subtle: #2b2b2b;
  --frame-bg: #050505;
  --frame-overlay-top: linear-gradient(180deg,
      color-mix(in srgb, #000000 32%, transparent) 0%,
      color-mix(in srgb, #000000 60%, transparent) 100%);
  --frame-overlay-bottom: linear-gradient(0deg,
      color-mix(in srgb, #000000 22%, transparent) 0%,
      transparent 62%);
  --frame-brand-pill-bg: color-mix(in srgb, #000000 16%, transparent);
  --frame-brand-pill-border: color-mix(in srgb, #ffffff 24%, transparent);
  --frame-brand-pill-text: var(--color-text-primary);
}

.frame-layer {
  position: absolute;
  inset: 0;
}

.frame-layer--image {
  background-size: cover;
  background-position: center;
}

.is-hidden {
  display: none !important;
}

.frame-layer--border {
  border: 1px solid transparent;
}

/* ─────────────────────────────────────────
   Top Band (structural rule line)
   ───────────────────────────────────────── */

.top-band {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: calc(4px * var(--layout-scale));
}

.top-band--data {
  background: var(--color-text-primary);
}

.top-band--metric {
  background: var(--color-text-primary);
}

/* ─────────────────────────────────────────
   Decorative Elements (minimal for Swiss)
   ───────────────────────────────────────── */

.decor-orb-left {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 1px;
  height: 100%;
  border-radius: 0;
  background: color-mix(in srgb, var(--color-border-subtle) 30%, transparent);
}

.decor-blob-right {
  position: absolute;
  right: calc(48px * var(--layout-scale));
  top: 0;
  bottom: 0;
  width: 1px;
  height: 100%;
  border-radius: 0;
  background: color-mix(in srgb, var(--color-border-subtle) 30%, transparent);
}

.decor-wash-left {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: calc(4px * var(--layout-scale));
  width: 100%;
  background: var(--color-text-primary);
}

/* ─────────────────────────────────────────
   Quote mark
   ───────────────────────────────────────── */

.quote-mark {
  position: absolute;
  left: 8%;
  top: 7%;
  font-family: var(--font-display);
  font-size: calc(148px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 0.8;
  opacity: 0.12;
  color: var(--color-text-primary);
}

/* ─────────────────────────────────────────
   Content Shell
   ───────────────────────────────────────── */

.content-shell {
  --template-panel-padding: 34px;
  --template-heading-size: var(--token-type-heading);
  --template-heading-secondary-size: var(--template-heading-size);
  --template-heading-quote-size: var(--template-heading-size);
  --template-heading-line-height: 1.06;
  --template-heading-letter-spacing: -0.02em;
  --template-body-size: var(--token-type-body);
  --template-body-secondary-size: var(--template-body-size);
  --template-body-quote-size: var(--template-body-size);
  --template-body-line-height: 1.38;
  --template-body-color: var(--color-text-secondary);
  --template-flow-kicker: var(--token-space-2xs);
  --template-flow-heading: var(--token-space-xs);
  --template-flow-subheading: var(--token-space-2xs);
  --template-flow-section: var(--token-space-md);
  --template-check-item-size: 22px;
  --template-metric-value-size: var(--token-type-metric-value);
  --template-metric-label-size: var(--token-type-metric-label);

  position: relative;
  z-index: 10;
  display: flex;
  width: 100%;
  height: 100%;
  flex-direction: column;
  padding: calc(var(--content-inset) * var(--layout-scale) * var(--frame-space-scale));
}

.content-shell--data-topband {
  padding-top: calc((var(--content-inset) + 18px) * var(--layout-scale) * var(--frame-space-scale));
}

.content-shell--metric-topband {
  padding-top: calc((var(--content-inset) + 14px) * var(--layout-scale) * var(--frame-space-scale));
}

/* ─────────────────────────────────────────
   Template Variants
   ───────────────────────────────────────── */

.template-quote {
  --template-panel-padding: 34px;
  --template-heading-quote-size: 56px;
  --template-body-quote-size: 24px;
  --template-body-secondary-size: 24px;
  --template-flow-kicker: var(--token-space-sm);
  --template-flow-heading: var(--token-space-sm);
}

.template-checklist {
  --template-panel-padding: 32px;
  --template-heading-secondary-size: 54px;
  --template-flow-section: var(--token-space-sm);
}

.template-metric {
  --template-panel-padding: 30px;
  --template-heading-secondary-size: 54px;
  --template-body-secondary-size: 26px;
}

.template-promo {
  --template-panel-padding: 34px;
  --template-heading-size: 60px;
  --template-body-secondary-size: 26px;
}

.template-article {
  --template-panel-padding: 36px;
  --template-heading-size: 58px;
  --template-body-size: 26px;
  --template-body-line-height: 1.42;
}

.template-series {
  --template-panel-padding: 36px;
  --template-heading-size: 52px;
  --template-body-size: 26px;
  --template-body-line-height: 1.42;
}

.template-dark {
  --color-text-primary: #f2f2f2;
  --color-text-secondary: #d1d1d1;
  --color-text-muted: #9a9a9a;
  --color-surface-base: #070707;
  --color-surface-elevated: #131313;
  --color-border-subtle: #2b2b2b;
}

.rule-line--inverted {
  background: #ffffff;
}

.cta-pill--inverted {
  background: #ffffff;
  color: #000000;
}

.series-index {
  font-family: var(--font-body);
  font-size: calc(140px * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 700;
  line-height: 1;
  color: color-mix(in srgb, var(--color-text-primary) 10%, transparent);
  position: absolute;
  right: 0;
  top: -20px;
  z-index: -1;
}

.metric-container {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: calc(var(--token-space-md) * var(--layout-scale));
}


/* ─────────────────────────────────────────
   Alignment
   ───────────────────────────────────────── */

.align-left {
  align-items: flex-start;
  text-align: left;
}

.align-center {
  align-items: center;
  text-align: center;
}

.align-justify {
  align-items: flex-start;
  text-align: justify;
}

/* ─────────────────────────────────────────
   Content Panel & Limits
   ───────────────────────────────────────── */

.content-panel {
  padding: calc(var(--template-panel-padding) * var(--layout-scale) * var(--frame-space-scale));
}

/* Content position utilities */
.push-start {
  margin-bottom: auto;
}

.push-center {
  margin-top: auto;
  margin-bottom: auto;
}

.push-end {
  margin-top: auto;
}

.content-limit {
  max-width: var(--content-max-width);
}

.caption-limit {
  max-width: var(--caption-max-width);
}

.metric-content {
  max-width: calc(var(--content-max-width) - (220px * var(--layout-scale)));
}

.caption-limit-metric {
  max-width: calc(var(--caption-max-width) - (220px * var(--layout-scale)));
}

/* ─────────────────────────────────────────
   Kicker
   ───────────────────────────────────────── */

.kicker {
  margin-top: calc(var(--template-flow-kicker) * var(--layout-scale) * var(--frame-space-scale));
  font-family: var(--font-body);
  font-size: calc(var(--token-type-kicker) * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 500;
  line-height: 1.1;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  max-width: var(--content-max-width);
}

/* ─────────────────────────────────────────
   Headings (serif display)
   ───────────────────────────────────────── */

.heading-primary,
.heading-secondary,
.heading-quote {
  font-family: var(--font-display);
  font-weight: 700;
  line-height: var(--template-heading-line-height);
  letter-spacing: var(--template-heading-letter-spacing);
  text-shadow: var(--token-shadow-title);
  color: var(--color-text-primary);
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--heading-max-lines);
  line-clamp: var(--heading-max-lines);
}

.heading-primary {
  font-size: calc(var(--template-heading-size) * var(--layout-scale) * var(--frame-type-scale));
}

.heading-secondary {
  font-size: calc(var(--template-heading-secondary-size) * var(--layout-scale) * var(--frame-type-scale));
}

.heading-quote {
  font-size: calc(var(--template-heading-quote-size) * var(--layout-scale) * var(--frame-type-scale));
  font-style: italic;
}

/* ─────────────────────────────────────────
   Body Text
   ───────────────────────────────────────── */

.body-primary,
.body-secondary,
.body-quote-attribution {
  font-family: var(--font-body);
  line-height: var(--template-body-line-height);
  color: var(--template-body-color);
  text-shadow: var(--token-shadow-caption);
}

.body-primary {
  font-size: calc(var(--template-body-size) * var(--layout-scale) * var(--frame-type-scale));
  font-style: italic;
}

.body-secondary {
  font-size: calc(var(--template-body-secondary-size) * var(--layout-scale) * var(--frame-type-scale));
}

.body-quote-attribution {
  font-size: calc(var(--template-body-quote-size) * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 600;
}

/* ─────────────────────────────────────────
   Flow (vertical rhythm)
   ───────────────────────────────────────── */

.flow-after-kicker {
  margin-top: calc(var(--template-flow-kicker) * var(--layout-scale) * var(--frame-space-scale));
}

.flow-after-heading {
  margin-top: calc(var(--template-flow-heading) * var(--layout-scale) * var(--frame-space-scale));
}

.flow-after-subheading {
  margin-top: calc(var(--template-flow-subheading) * var(--layout-scale) * var(--frame-space-scale));
}

.flow-after-section {
  margin-top: calc(var(--template-flow-section) * var(--layout-scale) * var(--frame-space-scale));
}

/* ─────────────────────────────────────────
   Top Bar (brand badge row)
   ───────────────────────────────────────── */

.top-bar {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: calc(20px * var(--layout-scale));
}

.top-bar-right {
  margin-left: auto;
}

.brand-pill {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  border-radius: 0;
  border: 1px solid var(--frame-brand-pill-border);
  background: var(--frame-brand-pill-bg);
  color: var(--frame-brand-pill-text);
  padding: calc(8px * var(--layout-scale) * var(--frame-space-scale)) calc(16px * var(--layout-scale) * var(--frame-space-scale));
  font-family: var(--font-body);
  font-size: calc(14px * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  line-height: 1.1;
}

.brand-icon {
  height: 1em;
  width: auto;
  margin-right: calc(6px * var(--layout-scale));
  vertical-align: middle;
  object-fit: contain;
}

/* ─────────────────────────────────────────
   Brand Icon Corner (positioned overlay)
   ───────────────────────────────────────── */

.brand-icon-corner {
  position: absolute;
  z-index: 20;
  padding: calc(24px * var(--layout-scale));
}

.brand-icon-corner.corner-top-left {
  top: 0;
  left: 0;
}

.brand-icon-corner.corner-top-right {
  top: 0;
  right: 0;
}

.brand-icon-corner.corner-bottom-left {
  bottom: 0;
  left: 0;
}

.brand-icon-corner.corner-bottom-right {
  bottom: 0;
  right: 0;
}

.brand-icon-img {
  height: calc(32px * var(--layout-scale));
  width: auto;
  object-fit: contain;
}

/* ─────────────────────────────────────────
   Meta Footer
   ───────────────────────────────────────── */

.meta-footer {
  margin-top: auto;
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  color: var(--color-text-muted);
  font-family: var(--font-body);
  font-size: calc(16px * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 500;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  line-height: 1.2;
}

/* ─────────────────────────────────────────
   Author Attribution Block
   ───────────────────────────────────────── */

.author-block {
  margin-top: calc(var(--token-space-sm) * var(--layout-scale) * var(--frame-space-scale));
}

.author-byline {
  font-family: var(--font-body);
  font-size: calc(18px * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text-primary);
  line-height: 1.2;
}

.author-date {
  font-family: var(--font-body);
  font-size: calc(18px * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 400;
  font-style: italic;
  color: var(--color-text-muted);
  line-height: 1.3;
  margin-top: calc(2px * var(--layout-scale));
}

/* ─────────────────────────────────────────
   Series Number Badge
   ───────────────────────────────────────── */

.series-number {
  font-family: var(--font-body);
  font-size: calc(18px * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  padding-bottom: calc(var(--token-space-xs) * var(--layout-scale));
  border-bottom: 2px solid var(--color-text-primary);
  display: inline-block;
  margin-bottom: calc(var(--token-space-md) * var(--layout-scale));
}

/* ─────────────────────────────────────────
   Horizontal Rule
   ───────────────────────────────────────── */

.rule-line {
  width: 100%;
  height: 1px;
  background: var(--color-border-subtle);
  margin: calc(var(--token-space-sm) * var(--layout-scale) * var(--frame-space-scale)) 0;
}

.rule-line--thick {
  height: 2px;
  background: var(--color-text-primary);
}

/* ─────────────────────────────────────────
   Checklist
   ───────────────────────────────────────── */

.checklist-list {
  display: flex;
  flex-direction: column;
  gap: calc(10px * var(--layout-scale) * var(--frame-space-scale));
}

.check-item {
  border-radius: 0;
  border: 1px solid var(--color-border-subtle);
  background: var(--color-surface-elevated);
  padding: calc(12px * var(--layout-scale) * var(--frame-space-scale)) calc(14px * var(--layout-scale) * var(--frame-space-scale));
  font-family: var(--font-body);
  font-size: calc(var(--template-check-item-size) * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.25;
  color: var(--color-text-primary);
}

/* ─────────────────────────────────────────
   Metric
   ───────────────────────────────────────── */

.metric-layout {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: calc(18px * var(--layout-scale) * var(--frame-space-scale));
}

.metric-card {
  min-width: calc(220px * var(--layout-scale));
  border-radius: 0;
  border: 2px solid var(--color-text-primary);
  background: var(--color-surface-elevated);
  padding: calc(14px * var(--layout-scale) * var(--frame-space-scale)) calc(16px * var(--layout-scale) * var(--frame-space-scale));
}

.metric-value {
  font-family: var(--font-display);
  font-size: calc(var(--template-metric-value-size) * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1;
  color: var(--color-text-primary);
}

.metric-label {
  font-family: var(--font-body);
  font-size: calc(var(--template-metric-label-size) * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.2;
  color: var(--color-text-secondary);
}

/* ─────────────────────────────────────────
   CTA Pill
   ───────────────────────────────────────── */

.cta-pill {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  border-radius: 0;
  background: var(--color-text-primary);
  color: var(--color-surface-base);
  padding: calc(12px * var(--layout-scale) * var(--frame-space-scale)) calc(24px * var(--layout-scale) * var(--frame-space-scale));
  font-family: var(--font-body);
  font-size: calc(22px * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  line-height: 1.1;
}

/* ─────────────────────────────────────────
   Article Card Image Area
   ───────────────────────────────────────── */

.article-image-area {
  position: relative;
  width: 100%;
  flex: 1;
  min-height: 40%;
  overflow: hidden;
}

.article-image-area .frame-layer--image {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
}

/* ─────────────────────────────────────────
   Structural Layouts (swap-friendly items)
   ───────────────────────────────────────── */

.template-editorial-mosaic {
  --template-heading-size: 56px;
  --template-body-size: 24px;
}

.mosaic-hero-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: calc(10px * var(--layout-scale));
}

.mosaic-tile {
  min-height: calc(84px * var(--layout-scale));
  border: 0;
  background: color-mix(in srgb, var(--color-surface-elevated) 92%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: calc(10px * var(--layout-scale));
  font-family: var(--font-body);
  font-size: calc(16px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.2;
  color: var(--color-text-secondary);
}

.mosaic-tile--wide {
  grid-column: span 2;
}

.editorial-story-block {
  border: 0;
  background: color-mix(in srgb, var(--color-surface-base) 94%, transparent);
  padding: calc(22px * var(--layout-scale) * var(--frame-space-scale));
}

.editorial-meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: calc(10px * var(--layout-scale));
  align-items: center;
}

.editorial-meta {
  font-family: var(--font-body);
  font-size: calc(16px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.2;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.template-split-copy-media {
  --template-panel-padding: 0;
  --template-heading-size: 58px;
  --template-body-size: 28px;
  padding: 0;
}

.template-split-copy-media .content-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  margin-top: 0;
  margin-bottom: 0;
  padding: 0;
}

.template-split-copy-media .top-bar {
  padding: calc(22px * var(--layout-scale) * var(--frame-space-scale));
}

.split-copy-stack {
  border: 0;
  background: color-mix(in srgb, var(--color-overlay-strong) 16%, transparent);
  padding: calc(26px * var(--layout-scale) * var(--frame-space-scale));
  flex: 0 0 50%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.split-media-band {
  min-height: 0;
  border: 0;
  background: color-mix(in srgb, var(--color-overlay-strong) 12%, transparent);
  display: flex;
  align-items: flex-end;
  justify-content: flex-start;
  padding: 0;
  flex: 1 1 50%;
  position: relative;
  overflow: hidden;
}

.split-media-image {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.split-media-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    0deg,
    color-mix(in srgb, var(--color-overlay-strong) 48%, transparent) 0%,
    transparent 68%
  );
}

.split-media-caption {
  position: relative;
  z-index: 1;
  margin: 0;
  padding: calc(18px * var(--layout-scale) * var(--frame-space-scale));
  font-family: var(--font-body);
  font-size: calc(18px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.3;
  color: var(--color-text-primary);
}

.template-concept-explainer {
  --template-panel-padding: 0;
  --template-heading-size: 62px;
  --template-body-size: 26px;
  padding: 0;
}

.template-concept-explainer .content-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  margin-top: 0;
  margin-bottom: 0;
  padding: 0;
}

.template-concept-explainer .top-bar {
  padding: calc(22px * var(--layout-scale) * var(--frame-space-scale));
}

.concept-media-band {
  position: relative;
  flex: 0 0 44%;
  min-height: 0;
  overflow: hidden;
}

.concept-media-image {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.concept-media-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    0deg,
    color-mix(in srgb, var(--color-overlay-strong) 44%, transparent) 0%,
    transparent 64%
  );
}

.concept-content {
  position: relative;
  z-index: 1;
  flex: 1 1 56%;
  min-height: 0;
  padding: calc(24px * var(--layout-scale) * var(--frame-space-scale));
  background: color-mix(in srgb, var(--color-overlay-strong) 16%, transparent);
}

.topic-chip {
  display: inline-flex;
  width: fit-content;
  padding: calc(8px * var(--layout-scale)) calc(18px * var(--layout-scale));
  border: 0;
  border-radius: 999px;
  font-family: var(--font-body);
  font-size: calc(20px * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text-primary);
  background: color-mix(in srgb, var(--color-overlay-strong) 18%, transparent);
}

.concept-callout {
  border: 0;
  background: color-mix(in srgb, var(--color-overlay-strong) 14%, transparent);
  padding: calc(20px * var(--layout-scale) * var(--frame-space-scale));
}

.concept-support-note {
  font-family: var(--font-body);
  font-size: calc(18px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.3;
  color: var(--color-text-muted);
}

.concept-corners {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.corner-chip {
  position: absolute;
  width: calc(120px * var(--layout-scale));
  height: calc(120px * var(--layout-scale));
  border-radius: 50%;
  border: 0;
  background: color-mix(in srgb, var(--color-overlay-strong) 18%, transparent);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: calc(12px * var(--layout-scale));
  font-family: var(--font-body);
  font-size: calc(14px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.2;
  color: var(--color-text-secondary);
}

.corner-chip--top {
  top: calc(16px * var(--layout-scale));
  right: calc(16px * var(--layout-scale));
}

.corner-chip--bottom {
  right: calc(20px * var(--layout-scale));
  bottom: calc(20px * var(--layout-scale));
}

.template-grid-item-card,
.template-grid-item-feature {
  --template-panel-padding: 0;
  padding: 0;
}

.template-grid-item-card .top-bar,
.template-grid-item-feature .top-bar {
  padding: calc(22px * var(--layout-scale) * var(--frame-space-scale));
}

.template-grid-item-card .content-panel,
.template-grid-item-feature .content-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  margin-top: 0;
  margin-bottom: 0;
  padding: 0;
}

.grid-item-card {
  min-height: 0;
  border: 0;
  background: transparent;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  flex: 1 1 auto;
  overflow: hidden;
  position: relative;
}

.grid-item-card--feature {
  min-height: 0;
}

.grid-item-media {
  flex: 0 0 50%;
  min-height: 0;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.grid-item-media-overlay {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 50%;
  background: linear-gradient(
    0deg,
    color-mix(in srgb, var(--color-overlay-strong) 36%, transparent) 0%,
    transparent 70%
  );
  pointer-events: none;
}

.grid-item-content {
  flex: 1 1 50%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: calc(12px * var(--layout-scale));
  padding: calc(24px * var(--layout-scale) * var(--frame-space-scale));
  background: color-mix(in srgb, var(--color-overlay-strong) 16%, transparent);
}

.grid-item-tag {
  font-family: var(--font-body);
  font-size: calc(16px * var(--layout-scale) * var(--frame-type-scale));
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.grid-item-title {
  margin: 0;
  font-family: var(--font-body);
  font-size: calc(44px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.06;
  color: var(--color-text-primary);
}

.grid-item-title--feature {
  font-size: calc(54px * var(--layout-scale) * var(--frame-type-scale));
}

.grid-item-body {
  margin: 0;
  font-family: var(--font-body);
  font-size: calc(22px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.26;
  color: var(--color-text-secondary);
}

.grid-item-body--feature {
  font-size: calc(24px * var(--layout-scale) * var(--frame-type-scale));
}

.grid-item-meta {
  margin: auto 0 0;
  font-family: var(--font-body);
  font-size: calc(16px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.2;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.template-overlap-stack {
  --template-panel-padding: 24px;
}

.stack-stage {
  position: relative;
  min-height: calc(540px * var(--layout-scale));
}

.stack-card {
  position: absolute;
  width: min(72%, calc(var(--content-max-width) * 0.72));
  border: 0;
  background: color-mix(in srgb, var(--color-surface-elevated) 95%, transparent);
  padding: calc(18px * var(--layout-scale) * var(--frame-space-scale));
  box-shadow: 0 calc(8px * var(--layout-scale)) calc(28px * var(--layout-scale)) color-mix(in srgb, var(--color-shadow-color, #000000) 10%, transparent);
}

.stack-card--back {
  top: calc(20px * var(--layout-scale));
  left: calc(14px * var(--layout-scale));
}

.stack-card--middle {
  top: calc(148px * var(--layout-scale));
  right: calc(16px * var(--layout-scale));
}

.stack-card--front {
  top: calc(286px * var(--layout-scale));
  left: calc(26px * var(--layout-scale));
}

.stack-card-title {
  margin: 0;
  font-family: var(--font-body);
  font-size: calc(40px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.08;
  color: var(--color-text-primary);
}

.stack-card-meta {
  margin: calc(14px * var(--layout-scale)) 0 0;
  font-family: var(--font-body);
  font-size: calc(16px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.2;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.template-card-deck {
  --template-panel-padding: 24px;
}

.deck-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: calc(14px * var(--layout-scale));
}

.deck-card {
  min-height: calc(220px * var(--layout-scale));
  border: 0;
  background: color-mix(in srgb, var(--color-surface-elevated) 95%, transparent);
  padding: calc(16px * var(--layout-scale) * var(--frame-space-scale));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: calc(10px * var(--layout-scale));
}

.deck-card-title {
  margin: 0;
  font-family: var(--font-body);
  font-size: calc(24px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.16;
  color: var(--color-text-primary);
}

.deck-card-note {
  margin: 0;
  font-family: var(--font-body);
  font-size: calc(16px * var(--layout-scale) * var(--frame-type-scale));
  line-height: 1.24;
  color: var(--color-text-muted);
}

@media (max-width: 980px) {
  .deck-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* ─────────────────────────────────────────
   Utilities
   ───────────────────────────────────────── */

.text-balance {
  text-wrap: balance;
}

.word-safe {
  overflow-wrap: anywhere;
  word-break: break-word;
}

.tabular-nums {
  font-variant-numeric: tabular-nums;
}
